function dbSaveForce(){
  if(!_dbReady)return;
  // 최소 5초 간격 강제 (전투 중 저장 스팸 방지)
  const _now2=Date.now();
  if(_now2-_lastSaveTime<5000){if(!_saveDebounce)_saveDebounce=setTimeout(()=>{_saveDebounce=null;dbSaveForce()},5000-(_now2-_lastSaveTime));return}
  if(_saveDebounce)clearTimeout(_saveDebounce);_saveDebounce=null;
  if(_saving){_pendingForce=true;return}
  dbSave();
}

